// Hình riêng của công cụ; fallback về hình hạng mục nếu thiếu slug
// (phòng thủ — hiện đủ 120/120 nên fallback không bao giờ chạy).
export function toolArt(slug, categorySlug) {
  return ART[slug] || categoryArt(categorySlug);
}
